    SettingDef("ai_function_embedding_default_credentials", "String", description = "Default: . Tier: Beta. Name of the named collection used by the embedding functions (`aiEmbed`, `aiSimilarity`) when the call does not pass `credentials` in its parameter map. Empty means no default: such calls must pass `credentials` explicitly. These functions take `model` as a required positional argument, not from the named collection. Kept separate from `ai_function_text_default_credentials` because an embeddings endpoint differs from a chat one."),
    SettingDef("ai_function_text_default_credentials", "String", description = "Default: . Tier: Beta. Name of the named collection used by the text AI functions (`aiGenerate`, `aiClassify`, `aiFilter`, `aiExtract`, `aiTranslate`, `aiRedact`) when the call does not pass `credentials` in its parameter map. Empty means no default: such calls must pass `credentials` explicitly. A chat-completions endpoint differs from an embeddings one, so this is separate from `ai_function_embedding_default_credentials`."),
    SettingDef("allow_experimental_analyzer", "Bool", description = "Default: 1. Tier: Production. Allow the analyzer.", aliases = listOf("enable_analyzer")),
